BEGIN;
CREATE TYPE tracking_device_status AS ENUM ('ACTIVE','SUSPENDED','REVOKED');
CREATE TYPE tracking_trip_device_status AS ENUM ('ASSIGNED','UNASSIGNED','EXPIRED');
CREATE TABLE tracking_devices (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), operator_organization_id UUID NOT NULL REFERENCES operator_organizations(id), device_identifier_hash TEXT NOT NULL UNIQUE, device_secret_hash TEXT NOT NULL, label TEXT, status tracking_device_status NOT NULL DEFAULT 'ACTIVE', last_seen_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), revoked_at TIMESTAMPTZ);
CREATE TABLE tracking_trip_devices (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), trip_instance_id UUID NOT NULL REFERENCES catalog_trip_instances(id), device_id UUID NOT NULL REFERENCES tracking_devices(id), status tracking_trip_device_status NOT NULL DEFAULT 'ASSIGNED', assigned_by UUID NOT NULL REFERENCES identity_users(id), assigned_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), unassigned_at TIMESTAMPTZ);
CREATE UNIQUE INDEX tracking_trip_devices_active_trip_idx ON tracking_trip_devices(trip_instance_id) WHERE status='ASSIGNED';
CREATE TABLE tracking_positions (id BIGSERIAL PRIMARY KEY, trip_instance_id UUID NOT NULL REFERENCES catalog_trip_instances(id), device_id UUID NOT NULL REFERENCES tracking_devices(id), observed_at TIMESTAMPTZ NOT NULL, received_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), latitude NUMERIC(9,6) NOT NULL, longitude NUMERIC(9,6) NOT NULL, speed_kph NUMERIC(7,2), heading NUMERIC(6,2), accuracy_meters NUMERIC(8,2), sequence_number BIGINT NOT NULL, map_matched JSONB, quality_flags JSONB NOT NULL DEFAULT '{}'::JSONB, UNIQUE(device_id,sequence_number));
CREATE INDEX tracking_positions_trip_time_idx ON tracking_positions(trip_instance_id, observed_at DESC);
CREATE TABLE tracking_trip_state (trip_instance_id UUID PRIMARY KEY REFERENCES catalog_trip_instances(id), last_position_id BIGINT REFERENCES tracking_positions(id), progress_percent NUMERIC(5,2), estimated_arrival_at TIMESTAMPTZ, eta_confidence_minutes NUMERIC(8,2), delay_minutes INTEGER, stale_after TIMESTAMPTZ, updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE tracking_stop_events (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), trip_instance_id UUID NOT NULL REFERENCES catalog_trip_instances(id), trip_stop_id UUID NOT NULL REFERENCES catalog_trip_stops(id), event_type TEXT NOT NULL CHECK(event_type IN ('ARRIVED','DEPARTED','UNSCHEDULED_NEARBY')), detected_at TIMESTAMPTZ NOT NULL, position_id BIGINT REFERENCES tracking_positions(id), confidence NUMERIC(5,2), UNIQUE(trip_instance_id,trip_stop_id,event_type));
CREATE TABLE tracking_share_links (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), trip_instance_id UUID NOT NULL REFERENCES catalog_trip_instances(id), booking_id UUID REFERENCES booking_records(id), token_hash TEXT NOT NULL UNIQUE, expires_at TIMESTAMPTZ NOT NULL, revoked_at TIMESTAMPTZ, created_by UUID REFERENCES identity_users(id), created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE tracking_access_audit (id BIGSERIAL PRIMARY KEY, trip_instance_id UUID NOT NULL REFERENCES catalog_trip_instances(id), actor_user_id UUID REFERENCES identity_users(id), access_type TEXT NOT NULL, request_id UUID, occurred_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE tracking_incidents (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), trip_instance_id UUID NOT NULL REFERENCES catalog_trip_instances(id), incident_type TEXT NOT NULL CHECK(incident_type IN ('EMERGENCY','TRACKING_PROBLEM','ROUTE_DEVIATION','OFFLINE_DEVICE')), status TEXT NOT NULL DEFAULT 'OPEN', reported_by UUID REFERENCES identity_users(id), escalation_contacts JSONB NOT NULL DEFAULT '[]'::JSONB, details JSONB NOT NULL DEFAULT '{}'::JSONB, resolved_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE tracking_retention_policies (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), operator_organization_id UUID REFERENCES operator_organizations(id), retention_days INTEGER NOT NULL CHECK(retention_days BETWEEN 1 AND 3650), applies_to TEXT NOT NULL, UNIQUE(operator_organization_id,applies_to));
CREATE TABLE tracking_outbox (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), event_id UUID NOT NULL UNIQUE DEFAULT gen_random_uuid(), trip_instance_id UUID NOT NULL REFERENCES catalog_trip_instances(id), event_type TEXT NOT NULL CHECK(event_type IN ('vehicle.position.v1','trip.update.v1','service.alert.v1')), payload JSONB NOT NULL, occurred_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), published_at TIMESTAMPTZ, publish_attempts INTEGER NOT NULL DEFAULT 0, last_error TEXT);
CREATE INDEX tracking_outbox_idx ON tracking_outbox(occurred_at) WHERE published_at IS NULL;
COMMIT;
